        mov     ax, [strokeScene__sceneIndex]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [sceneFirstPath + bx]
        mov     bx, [strokeScene__p]
        add     ax, bx
        mov     [strokePath__pathIndex], ax
        call    strokePath
.L214:
        inc     word [strokeScene__p]
        jmp     .L213
.L215:
        ret

; ============================================== sub plot ====

plot:
; ---- putNumber( u16( x ) )
        mov     ax, [plot__x]
        mov     [putNumber__n], ax
        call    putNumber
; ---- space()
        call    space
; ---- putNumber( u16( y ) )
        mov     ax, [plot__y]
        mov     [putNumber__n], ax
        call    putNumber
; ---- newline()
        call    newline
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int21:
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        ret

